import re

LEVELS = {"DEBUG", "INFO", "WARN", "ERROR", "CRITICAL"}
PATTERN = re.compile(r"^(\d{4}-\d{2}-\d{2}) (\d{2}:\d{2}:\d{2}) \[(\w+)\] (.*)$")


def parse_log_line(line: str) -> dict | None:
    if not isinstance(line, str):
        return None
    match = PATTERN.match(line.strip())
    if not match:
        return None
    date, time, level, message = match.groups()
    level = level.upper().replace("WARNING", "WARN")
    if level not in LEVELS:
        return None
    return {"date": date, "time": time, "level": level, "message": message.strip()}

import re

LEVELS = {"DEBUG", "INFO", "WARN", "ERROR", "CRITICAL"}
PATTERN = re.compile(
    r"(\d{4})-(\d{2})-(\d{2})[ \t]+(\d{2}):(\d{2}):(\d{2})[ \t]+\[[ \t]*(\w+)[ \t]*\](.*)",
    re.DOTALL,
)


def parse_log_line(line: str) -> dict | None:
    if not isinstance(line, str):
        return None
    match = PATTERN.fullmatch(line.strip())
    if not match:
        return None
    year, month, day, hour, minute, second, level, message = match.groups()
    if not 1 <= int(month) <= 12 or not 1 <= int(day) <= 31:
        return None
    if int(hour) > 23 or int(minute) > 59 or int(second) > 59:
        return None
    level = level.upper()
    if level == "WARNING":
        level = "WARN"
    if level not in LEVELS:
        return None
    return {
        "date": f"{year}-{month}-{day}",
        "time": f"{hour}:{minute}:{second}",
        "level": level,
        "message": message.strip(),
    }

import re

_LINE = re.compile(
    r"([0-9]{4}-(?:0[1-9]|1[0-2])-(?:0[1-9]|[12][0-9]|3[01]))[ \t]+"
    r"((?:[01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9])[ \t]+"
    r"\[[ \t]*([A-Za-z]+)[ \t]*\](.*)",
    re.DOTALL,
)
_LEVELS = {"DEBUG", "INFO", "WARN", "ERROR", "CRITICAL"}


def parse_log_line(line: str) -> dict | None:
    if not isinstance(line, str):
        return None
    match = _LINE.fullmatch(line.strip())
    if match is None:
        return None
    date, time, level, message = match.groups()
    level = level.upper()
    level = "WARN" if level == "WARNING" else level
    if level not in _LEVELS:
        return None
    return {"date": date, "time": time, "level": level, "message": message.strip()}
